export class ErasureRequestRepository {
  async createOrResume(merchantId, customerId, key): Promise<ErasureRequestRow> {
    return transaction(async (client) => {
      await advisoryLock(client, `erasure:${merchantId}`);
      const byKey = await client.query(... WHERE merchant_id=$1 AND idempotency_key=$2 FOR UPDATE);
      if (byKey.rows[0]) {
        if (byKey.rows[0].customer_id !== customerId) throw 409 'idempotency key already used for a different customer';
        return await this.resumeIfFailed(client, byKey.rows[0]);
      }
      const byCustomer = await client.query(... WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE);
      if (byCustomer.rows[0]) return await this.resumeIfFailed(client, byCustomer.rows[0]);
      const inserted = await client.query(`INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key) VALUES($1,$2,$3) RETURNING *`);
      return inserted.rows[0];
    });
  }
  private async resumeIfFailed(client, row) {
    if (row.status !== 'failed') return row;
    const updated = await client.query(`UPDATE customers.erasure_requests SET status='pending', available_at=now(), updated_at=now() WHERE id=$1 RETURNING *`, [row.id]);
    return updated.rows[0];
  }
  async findForMerchant(merchantId, requestId) { SELECT * WHERE merchant_id AND id }
  async claim(): Promise<ErasureRequestRow | undefined> { ... }
  async recoverStuck(): update processing older than 60s → pending
  async markCompleted(client, id): update ... 
  async markFailed(id, code, attempts): status failed, last_error, available_at backoff
}
```

