export async function scrubStoredDocuments(merchantId: string, customerId: string): Promise<void> {
  const manifests = await pool.query(`SELECT id, object_key, document_type FROM operations.document_manifests WHERE merchant_id=$1 AND (customer_id=$2 OR document_type='customer_import')`, [merchantId, customerId]);
