export async function executeErasureRequest(request: ErasureRequestRow): Promise<void> {
  try {
    await transaction((client) => scrubCustomerRecords(client, request.merchant_id, request.customer_id));
  } catch → throw coded('database_cleanup_failed')
  try { await scrubStoredDocuments(...) } catch → 'document_cleanup_failed'
  try { await scrubProjections(...) } catch → 'projection_cleanup_failed'
  // final sweep to close races with in-flight projections
  try { await scrubProjections(...) } catch → 'projection_cleanup_failed'
  await transaction(async (client) => {
    await markCompleted(client, request.id);
    await addOutboxEvent(client, { eventType: CUSTOMER_ERASED, aggregateType: 'customer', aggregateId: customerId, merchantId, correlationId: uuid(), payload: { customerId, requestId: request.id } });
  });
}
