export async function startErasureWorker(signal: AbortSignal): Promise<void> {
  const repository = new ErasureRequestRepository();
  let lastRecovery = 0;
  while (!signal.aborted) {
    if (Date.now() - lastRecovery > 30_000) { await repository.recoverStuck(); lastRecovery = Date.now(); }
    const request = await repository.claim();
    if (!request) { await sleep(250); continue; }
    try { await executeErasureRequest(request); }
    catch (error) {
      const code = error instanceof ErasureStepError ? error.code : 'database_cleanup_failed';
      logger.error(...);
      await repository.markFailed(request.id, code, request.attempts);
    }
  }
}
