{"command":"create","path":"/workspace/source/packages/privacy/src/requests.ts","file_text":"import type pg from 'pg';
import { advisoryLock, pool, transaction } from '../../database/src/pool.js';
import { boundedExponentialBackoffSeconds } from '../../operations/src/retry-policy.js';
import type { ErasureRequestRow } from './shape.js';

const STUCK_PROCESSING_SECONDS = 60;

export class ErasureRequestRepository {
  /**
   * Creates the customer's erasure request, or returns the existing one.
   * Reusing an idempotency key across customers is rejected; a failed request
   * is queued again in place so reposting resumes it under the same ID.
   */
  async createOrResume(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestRow> {
    return transaction(async (client) => {
      await advisoryLock(client, `erasure-request:${merchantId}`);
      const byKey = await client.query<ErasureRequestRow>(
        `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND idempotency_key=$2 FOR UPDATE`,
        [merchantId, idempotencyKey],
      );
      if (byKey.rows[0]) {
        if (byKey.rows[0].customer_id !== customerId) {
          throw Object.assign(new Error('idempotency key already used for a different customer'), { statusCode: 409 });
        }
        return this.resumeIfFailed(client, byKey.rows[0]);
      }
      const byCustomer = await client.query<ErasureRequestRow>(
        `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
        [merchantId, customerId],
      );
      if (byCustomer.rows[0]) return this.resumeIfFailed(client, byCustomer.rows[0]);
      const inserted = await client.query<ErasureRequestRow>(
        `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key)
         VALUES($1,$2,$3) RETURNING *`,
        [merchantId, customerId, idempotencyKey],
      );
      return inserted.rows[0]!;
    });
  }

  private async resumeIfFailed(client: pg.PoolClient, row: ErasureRequestRow): Promise<ErasureRequestRow> {
    if (row.status !== 'failed') return row;
    const resumed = await client.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='pending', available_at=now(), updated_at=now()
       WHERE id=$1 RETURNING *`,
      [row.id],
    );
    return resumed.rows[0]!;
  }

  async findForMerchant(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  /** Claims the next runnable request; failed requests are retried until attempts are exhausted. */
  async claim(): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='processing', attempts=attempts+1, updated_at=now()
       WHERE id=(
         SELECT id FROM customers.erasure_requests
         WHERE (status='pending' OR (status='failed' AND attempts<max_attempts)) AND available_at<=now()
         ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1
       ) RETURNING *`,
    );
    return result.rows[0];
  }

  /** Returns requests abandoned by a crashed worker back to the pending queue. */
  async recoverStuck(): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='pending', available_at=now(), updated_at=now()
       WHERE status='processing' AND updated_at < now() - ($1 || ' seconds')::interval`,
      [STUCK_PROCESSING_SECONDS],
    );
  }

  async markCompleted(client: pg.PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed', last_error=NULL, completed_at=now(), updated_at=now()
       WHERE id=$1`,
      [requestId],
    );
  }

  async markFailed(requestId: string, code: string, attempts: number): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed', last_error=$2,
           available_at=now() + ($3 || ' seconds')::interval, updated_at=now()
       WHERE id=$1`,
      [requestId, code, boundedExponentialBackoffSeconds(attempts)],
    );
  }
}
"}

