async function readObject(objectKey: string): Promise<string | undefined> {
  try {
    const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
    const chunks: Buffer[] = [];
    for await (const chunk of stream) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
    return Buffer.concat(chunks).toString('utf8');
  } catch (error) {
    if ((error as { code?: string }).code === 'NoSuchKey') return undefined;
    throw error;
  }
}

/**
 * Rewrites retained financial documents (receipts, invoices) so they no longer
 * identify the customer, and deletes raw customer import artifacts that mention
 * the customer. Manifest rows stay so document counts remain consistent.
 */
export async function scrubStoredDocuments(merchantId: string, customerId: string): Promise<void> {
  const manifests = await pool.query<{ id: string; object_key: string; document_type: string }>(
    `SELECT id,object_key,document_type FROM operations.document_manifests
     WHERE merchant_id=$1 AND (customer_id=$2 OR document_type='customer_import')`,
    [merchantId, customerId],
  );
  for (const manifest of manifests.rows) {
    const content = await readObject(manifest.object_key);
    if (content === undefined) continue;
    if (manifest.document_type === 'customer_import') {
      if (!content.includes(customerId)) continue;
      await objectStore.removeObject(DOCUMENT_BUCKET, manifest.object_key);
      await pool.query(`DELETE FROM operations.document_manifests WHERE id=$1`, [manifest.id]);
      continue;
    }
    if (manifest.document_type !== 'receipt' && manifest.document_type !== 'invoice') continue;
    const document = JSON.parse(content) as Record<string, unknown>;
    if (!('customer' in document)) continue;
    document.customer = { erased: true };
    const body = JSON.stringify(document);
    await objectStore.putObject(DOCUMENT_BUCKET, manifest.object_key, body, Buffer.byteLength(body), {
      'Content-Type': 'application/json',
    });
    await pool.query(
      `UPDATE operations.document_manifests SET checksum=$2 WHERE id=$1`,
      [manifest.id, createHash('sha256').update(body).digest('hex')],
    );
  }
}

/** Removes the customer's read-model projections from Redis and OpenSearch. */
export async function scrubProjections(merchantId: string, customerId: string): Promise<void> {
  const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
  await redis.del(cacheKey, `${cacheKey}:activity`);
  try {
    await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}`, refresh: true });
  } catch (error) {
    const status = (error as { meta?: { statusCode?: number } }).meta?.statusCode;
    if (status !== 404) throw error;
  }
}
"}

{"command":"create","path":"/workspace/source/packages/privacy/src/erasure-service.ts","file_text":"import { v4 as uuid } from 'uuid';
import { EVENT_TYPES } from '../../contracts/src/events.js';
import { transaction } from '../../database/src/pool.js';
import { addOutboxEvent } from '../../messaging/src/outbox.js';
import { ErasureRequestRepository } from './requests.js';
import { scrubCustomerRecords, scrubProjections, scrubStoredDocuments } from './scrub.js';
import { ERASURE_ERROR_CODES, type ErasureRequestRow } from './shape.js';

export class ErasureStepError extends Error {
  constructor(readonly code: string, cause: unknown) {
    super(code, { cause: cause instanceof Error ? cause : undefined });
  }
}

async function runStep(code: string, step: () => Promise<void>): Promise<void> {
  try {
    await step();
  } catch (error) {
    throw new ErasureStepError(code, error);
  }
}

/**
 * Executes one erasure attempt. Each step is idempotent, so retrying a failed
 * request converges on the same result without repeating destructive work.
 * Projections are scrubbed again at the end to close the race with work that
 * was already in flight when the request started processing.
 */
export async function executeErasureRequest(
  request: ErasureRequestRow,
  repository = new ErasureRequestRepository(),
): Promise<void> {
  const { merchant_id: merchantId, customer_id: customerId } = request;
  await runStep(ERASURE_ERROR_CODES.database, () =>
    transaction((client) => scrubCustomerRecords(client, merchantId, customerId)));
  await runStep(ERASURE_ERROR_CODES.documents, () => scrubStoredDocuments(merchantId, customerId));
  await runStep(ERASURE_ERROR_CODES.projections, () => scrubProjections(merchantId, customerId));
  await runStep(ERASURE_ERROR_CODES.projections, () => scrubProjections(merchantId, customerId));
  await runStep(ERASURE_ERROR_CODES.database, () =>
    transaction(async (client) => {
      await repository.markCompleted(client, request.id);
      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASED,
        aggregateType: 'customer',
        aggregateId: customerId,
        merchantId,
        correlationId: uuid(),
        payload: { customerId, requestId: request.id },
      });
    }));
}
"}

{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-worker.ts","file_text":"import { logger } from '../../../packages/observability/src/logger.js';
import { executeErasureRequest, ErasureStepError } from '../../../packages/privacy/src/erasure-service.js';
import { ErasureRequestRepository } from '../../../packages/privacy/src/requests.js';
import { ERASURE_ERROR_CODES } from '../../../packages/privacy/src/shape.js';

/** Sweeps pending and retryable erasure requests and drives them to completion. */
export async function startErasureWorker(signal: AbortSignal): Promise<void> {
  const repository = new ErasureRequestRepository();
  let lastRecovery = 0;
  while (!signal.aborted) {
    if (Date.now() - lastRecovery > 30_000) {
      await repository.recoverStuck();
      lastRecovery = Date.now();
    }
    let request;
    try {
      request = await repository.claim();
    } catch (error) {
      logger.error({ error }, 'erasure request claim failed');
      await new Promise((resolve) => setTimeout(resolve, 1_000));
      continue;
    }
    if (!request) {
      await new Promise((resolve) => setTimeout(resolve, 250));
      continue;
    }
    try {
      await executeErasureRequest(request, repository);
      logger.info({ requestId: request.id }, 'erasure request completed');
    } catch (error) {
      const code = error instanceof ErasureStepError ? error.code : ERASURE_ERROR_CODES.database;
      logger.error({ error, requestId: request.id }, 'erasure request attempt failed');
      await repository.markFailed(request.id, code, request.attempts);
    }
  }
}
"}

