{"command":"create","path":"/workspace/source/tests/erasure.test.ts","file_text":"import assert from 'node:assert/strict';
import test from 'node:test';
import { randomUUID } from 'node:crypto';
import {
  erasedCustomerSnapshot,
  isValidErasureIdempotencyKey,
  scrubEventPayload,
  serializeErasureRequest,
  type ErasureRequestRow,
} from '../packages/privacy/src/shape.js';

test('erasure idempotency keys must be 8-200 characters', () => {
  assert.equal(isValidErasureIdempotencyKey('1234567'), false);
  assert.equal(isValidErasureIdempotencyKey('12345678'), true);
  assert.equal(isValidErasureIdempotencyKey('k'.repeat(200)), true);
  assert.equal(isValidErasureIdempotencyKey('k'.repeat(201)), false);
  assert.equal(isValidErasureIdempotencyKey(undefined), false);
  assert.equal(isValidErasureIdempotencyKey(12345678), false);
});

test('erasure request serialization exposes the public API shape without internal fields', () => {
  const row: ErasureRequestRow = {
    id: randomUUID(),
    merchant_id: randomUUID(),
    customer_id: randomUUID(),
    idempotency_key: 'secret-key-material',
    status: 'pending',
    attempts: 0,
    max_attempts: 8,
    last_error: null,
    available_at: new Date('2026-08-20T12:00:00.000Z'),
    created_at: new Date('2026-08-20T12:00:00.000Z'),
    updated_at: new Date('2026-08-20T12:00:00.000Z'),
    completed_at: null,
  };
  const view = serializeErasureRequest(row);
  assert.deepEqual(view, {
    id: row.id,
    customerId: row.customer_id,
    status: 'pending',
    attempts: 0,
    createdAt: '2026-08-20T12:00:00.000Z',
    updatedAt: '2026-08-20T12:00:00.000Z',
    completedAt: null,
    lastError: null,
  });
  assert.equal('merchant_id' in view, false);
  assert.equal('idempotency_key' in view, false);
});

test('erased snapshots keep the customer reference without personal data', () => {
  const customerId = randomUUID();
  assert.deepEqual(erasedCustomerSnapshot(customerId), { id: customerId, erased: true });
});

test('event payload scrubbing removes personal data but keeps financial meaning', () => {
  const scrubbed = scrubEventPayload({
    paymentId: randomUUID(),
    customerId: randomUUID(),
    amount: 2500,
